<?php $this->setLayout(''); $esc=static fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8'); ?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Invoice <?= $esc($invoice['invoice_number']) ?></title><style>body{margin:0;background:#f5f8f5;color:#193128;font:16px/1.5 system-ui,sans-serif}.wrap{max-width:720px;margin:48px auto;padding:0 18px}.card{background:white;border:1px solid #e2e9e4;border-radius:18px;padding:28px;box-shadow:0 15px 50px #133b2610}.top{display:flex;justify-content:space-between;gap:15px;border-bottom:1px solid #e9efeb;padding-bottom:18px}.muted{color:#66756d}.status{background:#fff3d9;color:#80580c;border-radius:30px;padding:5px 10px;font-size:12px;font-weight:700;height:max-content}.total{font-size:34px;font-weight:850;margin:4px 0 20px}.line{display:flex;justify-content:space-between;padding:13px 0;border-bottom:1px solid #edf1ee}.fee{background:#f4f8f4;padding:15px;border-radius:12px;margin-top:18px}.note{font-size:13px;color:#66756d;margin-top:20px} .btn{display:block;text-align:center;background:#147d58;color:white;text-decoration:none;padding:13px;border-radius:10px;font-weight:750;margin-top:20px}</style></head><body><main class="wrap"><div class="card"><div class="top"><div><div class="muted">INVOICE FROM</div><h2 style="margin:3px 0"><?= $esc($invoice['business_name']) ?></h2><div class="muted"><?= $esc($invoice['invoice_number']) ?></div></div><span class="status"><?= $esc(ucfirst($invoice['status'])) ?></span></div><p class="muted" style="margin-top:22px">BILL TO</p><b><?= $esc($invoice['customer_name']) ?></b><div class="muted"><?= $esc($invoice['customer_email']) ?></div><p class="muted" style="margin-top:25px">TOTAL DUE</p><div class="total"><?= $esc($invoice['currency']) ?> <?= number_format((float)$invoice['amount_due'],2) ?></div><?php foreach($invoice['items'] as $item): ?><div class="line"><div><?= $esc($item['description']) ?><div class="muted" style="font-size:13px"><?= $esc($item['quantity']) ?> × <?= number_format((float)$item['unit_price'],2) ?></div></div><b><?= number_format((float)$item['line_total'],2) ?></b></div><?php endforeach; ?><div class="line"><span>Subtotal</span><b><?= number_format((float)$invoice['subtotal'],2) ?></b></div><?php if((float)$invoice['tax_amount']>0): ?><div class="line"><span>Tax</span><b><?= number_format((float)$invoice['tax_amount'],2) ?></b></div><?php endif; ?><?php if((float)$invoice['discount_amount']>0): ?><div class="line"><span>Discount</span><b>−<?= number_format((float)$invoice['discount_amount'],2) ?></b></div><?php endif; ?><div class="fee"><b>Transaction fee policy: <?= $esc(ucfirst($invoice['fee_payer'])) ?> pays</b><div class="line"><span>Customer fee share</span><b><?= $esc($invoice['currency']) ?> <?= number_format((float)$invoice['customer_fee'],2) ?></b></div><div class="muted" style="font-size:13px">Total platform fee: <?= $esc($invoice['currency']) ?> <?= number_format((float)$invoice['platform_fee'],2) ?> · This page is an invoice, not a payment processor. Payment checkout must be connected before collecting money.</div></div><?php if($invoice['due_date']): ?><p class="note">Due date: <?= $esc($invoice['due_date']) ?></p><?php endif; ?><?php if($invoice['description']): ?><p><?= nl2br($esc($invoice['description'])) ?></p><?php endif; ?><p class="note">Questions? Contact <?= $esc($invoice['support_email']??'the business that sent this invoice') ?>.</p></div><p class="note" style="text-align:center">Powered by NairaBill</p></main></body></html>
